package com.matejpcs.netflared;
import java.io.IOException;import java.nio.file.Path;import java.util.*;import java.util.concurrent.CompletableFuture;import java.util.function.*;
public final class NetflaredService{public interface Sender{boolean admin();void send(String s);}public record ServerInfo(int port,String name){}private final ServerConfig c;private final CloudflaredManager cf;private final Supplier<ServerInfo>info;private final Consumer<Runnable>main;private volatile CloudflareClient client;private volatile List<CloudflareClient.Zone>zones=List.of();public NetflaredService(Path d,Supplier<ServerInfo>i,Consumer<Runnable>m)throws IOException{c=new ServerConfig(d);c.load();cf=new CloudflaredManager(d);info=i;main=m;}public void shutdown(){cf.stop();}public void autoConnect(){if(c.isConfigured())connect(null);}public void handle(Sender s,String[]a){if(!s.admin()){s.send("§cYou do not have permission to manage Netflared.");return;}String x=a.length==0?"status":a[0].toLowerCase(Locale.ROOT);switch(x){case"status"->status(s);case"info"->info(s);case"connect","start"->connect(s);case"disconnect","stop"->disconnect(s);case"reload"->reload(s);case"reset"->reset(s);case"setup"->setup(s,a);default->help(s);}}private void setup(Sender s,String[]a){if(a.length<2){s.send("§e/netflared setup <token>");s.send("§7/netflared setup select <number> [subdomain]");return;}if(a[1].equalsIgnoreCase("select")){if(a.length<3){s.send("§cChoose a zone number.");return;}try{select(s,Integer.parseInt(a[2]),a.length>3?a[3]:"play");}catch(NumberFormatException e){s.send("§cZone number must be a number.");}return;}begin(s,a[1]);}private void begin(Sender s,String t){if(t.length()<20){s.send("§cThat does not look like a Cloudflare API token.");return;}s.send("§eChecking Cloudflare API token...");CompletableFuture.runAsync(()->{try{CloudflareClient x=new CloudflareClient(t);x.verify();List<CloudflareClient.Zone>z=x.listZones();if(z.isEmpty())throw new IOException("No Cloudflare zones are visible to this token.");client=x;zones=z;main.accept(()->{s.send("§aCloudflare token accepted. Choose a domain:");for(int i=0;i<z.size();i++)s.send("§e"+(i+1)+"§7. "+z.get(i).name());s.send("§7/netflared setup select <number> [subdomain]");});}catch(Exception e){main.accept(()->s.send("§cSetup failed: "+e.getMessage()));}});}private void select(Sender s,int n,String sub){if(client==null||zones.isEmpty()){s.send("§cNo setup session is active.");return;}if(n<1||n>zones.size()){s.send("§cInvalid zone number.");return;}CloudflareClient.Zone z=zones.get(n-1);String h;try{h=Hostname.build(sub,z.name());}catch(Exception e){s.send("§c"+e.getMessage());return;}ServerInfo si=info.get();String rawName=("netflared-"+si.name().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9-]","-"));final String name=rawName.substring(0,Math.min(48,rawName.length()));s.send("§eCreating Cloudflare Tunnel for "+h+"...");CompletableFuture.runAsync(()->{try{CloudflareClient.Tunnel t=client.createTunnel(z.accountId(),name);String tok=client.getTunnelToken(z.accountId(),t.id());client.updateConfiguration(z.accountId(),t.id(),h,si.port());client.upsertDns(z.id(),h,t.id()+".cfargotunnel.com");c.setEnabled(true);c.setAccountId(z.accountId());c.setZoneId(z.id());c.setZoneName(z.name());c.setTunnelId(t.id());c.setTunnelName(t.name());c.setTunnelToken(tok);c.setHostname(h);c.setServerPort(si.port());c.save();main.accept(()->{s.send("§aNetflared setup complete.");s.send("§6Public address: §f"+h);connect(s);});}catch(Exception e){main.accept(()->s.send("§cSetup failed: "+e.getMessage()));}});}private void connect(Sender s){if(!c.isConfigured()){if(s!=null)s.send("§cNetflared is not configured.");return;}CompletableFuture.runAsync(()->{try{cf.ensureBinary();cf.start(c.tunnelToken());main.accept(()->{if(s!=null)s.send("§aCloudflared started.");});}catch(Exception e){main.accept(()->{if(s!=null)s.send("§cCould not start tunnel: "+e.getMessage());});}});}private void disconnect(Sender s){cf.stop();if(s!=null)s.send("§eCloudflared stopped.");}private void status(Sender s){if(!c.isConfigured()){s.send("§eNetflared is not configured.");return;}s.send("§6Netflared status");s.send("§7Address: §f"+c.hostname());s.send("§7Local: §f127.0.0.1:"+c.serverPort());s.send("§7Tunnel: "+(cf.isRunning()?"§aCONNECTED":"§cSTOPPED"));}private void info(Sender s){s.send("§6Netflared configuration");s.send("§7Public hostname: §f"+c.hostname());s.send("§7Minecraft port: §f"+c.serverPort());s.send("§7Cloudflare zone: §f"+c.zoneName());s.send("§7Tunnel: §f"+c.tunnelName());s.send("§7Platform: §f"+Platform.id());s.send("§7cloudflared: §f"+cf.binary());}private void reload(Sender s){try{c.load();cf.stop();if(c.isConfigured())connect(s);else s.send("§eConfiguration reloaded; Netflared is not configured.");}catch(IOException e){s.send("§cReload failed: "+e.getMessage());}}private void reset(Sender s){disconnect(null);try{c.setEnabled(false);c.setTunnelToken("");c.setTunnelId("");c.setTunnelName("");c.setHostname("");c.save();cf.clearTokenFile();s.send("§aLocal configuration reset. Cloudflare resources were left untouched.");}catch(IOException e){s.send("§cReset failed: "+e.getMessage());}}private void help(Sender s){s.send("§6Netflared Server");s.send("§7/netflared status");s.send("§7/netflared info");s.send("§7/netflared setup <token>");s.send("§7/netflared setup select <number> [subdomain]");s.send("§7/netflared connect|disconnect|reload|reset");}}
